{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Norethisterone, which shares the 3-keto-4-ene and 17α-ethynyl-17β-hydroxy pharmacophore with the query, has an absolute oral bioavailability of 64% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Levonorgestrel, a 13-ethyl analogue with the same 17α-ethynyl-17β-hydroxy-3-keto-4-ene core, has a mean absolute bioavailability of 94% across three human studies, strongly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Etonogestrel, another close progestin analogue, has an absolute bioavailability of 79.2 ± 7.7% in healthy women, supporting high oral bioavailability for this steroid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Abiraterone, the most similar retrieved molecule by Morgan score, has <10% oral bioavailability in humans; however, it lacks the 17α-ethynyl-17β-hydroxy-3-keto-4-ene motif and instead has a 3β-hydroxy-5-ene/17-pyridyl structure, making this low-F evidence only weakly transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 17α-ethynyl-17β-hydroxy-3-keto-4-ene steroid with an additional 16-aryl group. Multiple close progestin analogues (norethisterone, levonorgestrel, etonogestrel) have absolute oral bioavailability of 64–94%, strongly supporting F ≥ 20%. The only low-F analogue with higher Morgan similarity, abiraterone, lacks the key 17α-ethynyl-17β-hydroxy-3-keto-4-ene motif and is therefore less transferable. Overall, high oral bioavailability is better supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability study exists for the exact query molecule.",
    "The 16-(4-dimethylaminophenyl) substituent is not represented in the high-F progestin evidence; its effect on solubility, permeability, or first-pass metabolism is uncertain.",
    "Abiraterone low-F evidence is structurally related but lacks the 17α-ethynyl-17β-hydroxy-3-keto-4-ene motif, limiting its transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

